blockoverride "header_button_text_layout" {
	hbox = {
		# CM: mass auto-expand RGO button, in front of the button's text
		cm_mass_auto_expand_rgo_button = {}

		# the beta's own vbox of header_button_template's "header_button_text_layout" block (main_menu/gui/shared/main_menu_buttons.gui)
		vbox = {
			using = layoutpolicy_expanding
			block "header_button_template_minimumsize"{
				minimumsize = { -1 40 }
			}

			block "header_button_text_margins" {}

			expand = {}

			text_single = {
				fontsize = 15

				block "text_top" {
					visible = no
				}

				block "header_button_text_align" {}
			}

			block "header_button_text_bottom" {
				text_single = {
					fontsize = 12

					block "text_bottom" {
						visible = no
					}

					block "header_button_text_align" {}
				}
			}

			expand = {}
		}
	}
}
